640	/// - [Result]: if the given options are incompatible
641	/// - [Option]: if no fixes are requested
642	/// - [FixFileMode]: if safe or unsafe fixes are requested
643	pub(crate) fn determine_fix_file_mode(
644	    options: FixFileModeOptions,
645	    console: &mut dyn Console,
646	) -> Result<Option<FixFileMode>, CliDiagnostic> {
647	    let FixFileModeOptions {
648	        apply,
649	        apply_unsafe,
650	        write,
651	        fix,
652	        unsafe_,
653	    } = options;
654	
655	    if apply || apply_unsafe {
656	        let (deprecated, alternative) = if apply {
657	            ("--apply", "--write")
658	        } else {
659	            ("--apply-unsafe", "--write --unsafe")
660	        };
661	        let diagnostic = DeprecatedArgument::new(markup! {
662	            "The argument "<Emphasis>{deprecated}</Emphasis>" is deprecated, it will be removed in the next major release. Use "<Emphasis>{alternative}</Emphasis>" instead."
663	        });
664	        console.error(markup! {{PrintDiagnostic::simple(&diagnostic)}});
665	    }
666	
667	    check_fix_incompatible_arguments(options)?;
668	
669	    let safe_fixes = apply || write || fix;
670	    let unsafe_fixes = apply_unsafe || ((write || safe_fixes) && unsafe_);
671	
672	    if unsafe_fixes {
673	        Ok(Some(FixFileMode::SafeAndUnsafeFixes))
674	    } else if safe_fixes {
675	        Ok(Some(FixFileMode::SafeFixes))
676	    } else {
677	        Ok(None)
678	    }
679	}
