681	/// Checks if the fix file options are incompatible.
682	fn check_fix_incompatible_arguments(options: FixFileModeOptions) -> Result<(), CliDiagnostic> {
683	    let FixFileModeOptions {
684	        apply,
685	        apply_unsafe,
686	        write,
687	        fix,
688	        unsafe_,
689	    } = options;
690	    if apply && apply_unsafe {
691	        return Err(CliDiagnostic::incompatible_arguments(
692	            "--apply",
693	            "--apply-unsafe",
694	        ));
695	    } else if apply_unsafe && unsafe_ {
696	        return Err(CliDiagnostic::incompatible_arguments(
697	            "--apply-unsafe",
698	            "--unsafe",
699	        ));
700	    } else if apply && (fix || write) {
701	        return Err(CliDiagnostic::incompatible_arguments(
702	            "--apply",
703	            if fix { "--fix" } else { "--write" },
704	        ));
705	    } else if apply_unsafe && (fix || write) {
706	        return Err(CliDiagnostic::incompatible_arguments(
707	            "--apply-unsafe",
708	            if fix { "--fix" } else { "--write" },
709	        ));
710	    } else if write && fix {
711	        return Err(CliDiagnostic::incompatible_arguments("--write", "--fix"));
712	    }
713	    Ok(())
714	}
